1	#!/usr/bin/env bun
2	/**
3	 * ============================================================================
4	 * INFERENCE - Unified inference tool with three run levels + advisor escalation
5	 * ============================================================================
6	 *
7	 * PURPOSE:
8	 * Single inference tool with configurable speed/capability trade-offs:
9	 * - Fast: Haiku - quick tasks, simple generation, basic classification
10	 * - Standard: Sonnet - balanced reasoning, typical analysis
11	 * - Smart: Opus - deep reasoning, strategic decisions, complex analysis
12	 * - Advisor: Smart-tier escalation for commitment-boundary review (Algorithm v3.23+ VERIFY doctrine)
13	 *
14	 * USAGE:
15	 *   bun Inference.ts --level fast <system_prompt> <user_prompt>
16	 *   bun Inference.ts --level standard <system_prompt> <user_prompt>
17	 *   bun Inference.ts --level smart <system_prompt> <user_prompt>
18	 *   bun Inference.ts --mode advisor <task> <state> <question>
19	 *   bun Inference.ts --mode advisor --auto-state <task> <question>   (v3.24 P5)
20	 *   bun Inference.ts --json --level fast <system_prompt> <user_prompt>
21	 *
22	 * OPTIONS:
23	 *   --level <fast|standard|smart>  Run level (default: standard)
24	 *   --mode advisor                 Advisor escalation mode — 3 positional args: task, state, question
25	 *   --auto-state                   v3.24 P5: Auto-synthesize state from current ISA + recent activity (advisor mode only, 2 positional args: task, question)
26	 *   --json                         Expect and parse JSON response
27	 *   --opencode                     Route through InferenceOpencode.ts (GPT-5.5 via local OpenCode server); falls back to Claude if unavailable
28	 *   --timeout <ms>                 Custom timeout (default varies by level)
29	 *
30	 * DEFAULTS BY LEVEL:
31	 *   fast:     model=haiku,   timeout=15s
32	 *   standard: model=sonnet,  timeout=30s
33	 *   smart:    model=opus,    timeout=90s
34	 *   advisor:  model=opus,    timeout=120s
35	 *
36	 * BILLING: Uses Claude CLI with subscription (not API key)
37	 * CACHE: Uses --exclude-dynamic-system-prompt-sections for cross-invocation prompt cache hits
38	 *
39	 * ADVISOR PATTERN (v3.24 Verification Doctrine — see PAI/ALGORITHM/v3.24.0.md):
40	 *   The advisor() function implements the Sonnet→Opus escalation checkpoint rule
41	 *   from R Amjad's Anthropic Advisor tool writeup. Call at commitment boundaries:
42	 *   - Before committing to an approach
43	 *   - When stuck or diverging
44	 *   - Once after a durable deliverable, before declaring done
45	 *   Skip for short reactive tasks (measured: <4 min AND <2 files — v3.24 P2).
46	 *   On Extended+ ISAs, phase:complete transition = MANDATORY advisor call (v3.24 P4).
47	 *
48	 *   Unlike Anthropic's native Advisor which receives the full CC session, this
49	 *   function takes explicit (task, state, question) parameters. The caller may
50	 *   supply state manually OR set autoSynthesize: true to have the helper read
51	 *   the current ISA + recent activity automatically (v3.24 P5 — closes the
52	 *   state-gaming escape hatch where the caller cherry-picks what the reviewer sees).
53	 *
54	 *   Conflict-surfacing rule: if empirical results contradict advisor output,
55	 *   re-call advisor with the conflict surfaced — do NOT silently switch. Max 2
56	 *   re-calls on the same conflict; after that, escalate to user (v3.24 P1).
57	 *
58	 * ============================================================================
59	 */
60	
61	import { spawn } from "child_process";
62	import { join } from "path";
63	
64	export type InferenceLevel = 'fast' | 'standard' | 'smart';
65	
66	export interface InferenceOptions {
67	  systemPrompt: string;
68	  userPrompt: string;
69	  level?: InferenceLevel;
70	  expectJson?: boolean;
71	  timeout?: number;
72	  /** Optional image file paths. When provided, Read tool is enabled and paths
73	   * are prepended to the user prompt as @-references so Claude reads them as
74	   * image attachments. Routes through subscription like all other inference. */
75	  imagePaths?: string[];
76	  /** Opt-in: route this call through InferenceOpencode.ts (GPT-5.5 via the local
77	   * OpenCode server at localhost:7878) instead of the Claude CLI. When the
78	   * OpenCode server is unavailable, the call transparently falls back to Claude.
79	   * Existing callers that omit this flag are completely unchanged. */
80	  useOpencode?: boolean;
81	}
82	
83	export interface InferenceResult {
84	  success: boolean;
85	  output: string;
86	  parsed?: unknown;
87	  error?: string;
88	  latencyMs: number;
89	  level: InferenceLevel;
90	}
91	
92	// Level configurations
93	const LEVEL_CONFIG: Record<InferenceLevel, { model: string; defaultTimeout: number }> = {
94	  fast: { model: 'haiku', defaultTimeout: 15000 },
95	  standard: { model: 'sonnet', defaultTimeout: 30000 },
96	  smart: { model: 'opus', defaultTimeout: 90000 },
97	};
98	
99	// Advisor-specific defaults (v3.23 VERIFY doctrine).
100	const ADVISOR_TIMEOUT_MS = 120000;
101	
102	/** Shape of the single JSON line emitted by InferenceOpencode.ts. */
103	interface OpencodeFinalLine {
104	  verdict: string;
105	  final_message?: string;
106	  reason?: string;
107	}
108	
109	/**
110	 * Extract the first JSON object or array that successfully parses from `text`,
111	 * preferring an object match and falling back to an array match. Mirrors the
112	 * JSON-extraction logic used on the Claude path so `expectJson` behaves
113	 * identically regardless of which backend produced the output.
114	 *
115	 * Returns the parsed value, or undefined when neither candidate parses.
116	 */
117	function tryExtractJson(text: string): unknown {
118	  const objectMatch = text.match(/\{[\s\S]*\}/);
119	  const arrayMatch = text.match(/\[[\s\S]*\]/);
120	  for (const candidate of [objectMatch?.[0], arrayMatch?.[0]]) {
121	    if (!candidate) continue;
122	    try {
123	      return JSON.parse(candidate);
124	    } catch {
125	      /* try next candidate */
126	    }
127	  }
128	  return undefined;
129	}
130	
131	/**
132	 * Route an inference call through InferenceOpencode.ts (GPT-5.5 via the local
133	 * OpenCode server). The caller is responsible for checking
134	 * `options.useOpencode === true` before invoking this.
135	 *
136	 * Returns an InferenceResult. The sentinel `error: 'opencode_unavailable'` tells
137	 * inference() that the OpenCode server is down so it can fall back to Claude;
138	 * every other failure is a terminal result the caller should surface as-is.
139	 */
140	async function inferenceViaOpencode(options: InferenceOptions): Promise<InferenceResult> {
141	  const level = options.level || 'standard';
142	  const config = LEVEL_CONFIG[level];
143	  const startTime = Date.now();
144	  const timeout = options.timeout || config.defaultTimeout;
145	
146	  // Build the combined prompt. The OpenCode bridge takes a single prompt string,
147	  // so fold the system prompt in as a labeled prefix when present.
148	  const combinedPrompt = options.systemPrompt
149	    ? `SYSTEM: ${options.systemPrompt}\n\nUSER: ${options.userPrompt}`
150	    : `USER: ${options.userPrompt}`;
151	
152	  const slug = `inference-${Date.now()}`;
153	  const scriptPath = join(process.env.HOME || '', '.claude', 'PAI', 'TOOLS', 'InferenceOpencode.ts');
154	  const args = [
155	    scriptPath,
156	    '--slug', slug,
157	    '--prompt', combinedPrompt,
158	    '--timeout-ms', String(timeout),
159	  ];
160	
161	  return new Promise<InferenceResult>((resolve) => {
162	    let stdout = '';
163	    let stderr = '';
164	    let settled = false;
165	
166	    const finish = (result: InferenceResult) => {
167	      if (settled) return;
168	      settled = true;
169	      clearTimeout(timeoutId);
170	      resolve(result);
171	    };
172	
173	    const proc = spawn('bun', args, {
174	      stdio: ['ignore', 'pipe', 'pipe'],
175	    });
176	
177	    // Give the bridge a generous grace window beyond its own internal timeout so
178	    // the JSON `timeout` verdict can surface normally; only hard-kill if the
179	    // child overruns even that, which indicates a hung process.
180	    const KILL_GRACE_MS = 5000;
181	    const timeoutId = setTimeout(() => {
182	      proc.kill('SIGKILL');
183	      finish({
184	        success: false,
185	        output: '',
186	        error: `OpenCode timeout after ${timeout}ms`,
187	        latencyMs: Date.now() - startTime,
188	        level,
189	      });
190	    }, timeout + KILL_GRACE_MS);
191	
192	    proc.stdout.on('data', (data) => {
193	      stdout += data.toString();
194	    });
195	
196	    proc.stderr.on('data', (data) => {
197	      stderr += data.toString();
198	    });
199	
200	    proc.on('error', (err) => {
201	      finish({
202	        success: false,
203	        output: '',
204	        error: `failed to spawn opencode bridge: ${err.message}`,
205	        latencyMs: Date.now() - startTime,
206	        level,
207	      });
208	    });
209	
210	    proc.on('close', () => {
211	      const latencyMs = Date.now() - startTime;
212	
213	      // The bridge writes its result as the last non-empty line of stdout.
214	      // Diagnostics go to stderr, so stdout should be clean JSON — but parse the
215	      // last non-empty line defensively in case anything else is interleaved.
216	      const lines = stdout.split('\n').map((l) => l.trim()).filter((l) => l.length > 0);
217	      const lastLine = lines.length > 0 ? lines[lines.length - 1] : '';
218	
219	      let result: OpencodeFinalLine;
220	      try {
221	        result = JSON.parse(lastLine) as OpencodeFinalLine;
222	      } catch {
223	        const detail = (stderr.trim() || stdout.trim()).slice(0, 200);
224	        finish({
225	          success: false,
226	          output: '',
227	          error: `failed to parse opencode output: ${detail}`,
228	          latencyMs,
229	          level,
230	        });
231	        return;
232	      }
233	
234	      if (result.verdict === 'unavailable') {
235	        // Sentinel: inference() detects this and falls back to Claude.
236	        finish({
237	          success: false,
238	          output: '',
239	          error: 'opencode_unavailable',
240	          latencyMs,
241	          level,
242	        });
243	        return;
244	      }
245	
246	      if (result.verdict === 'success') {
247	        const output = (result.final_message || '').trim();
248	        if (options.expectJson) {
249	          const parsed = tryExtractJson(output);
250	          if (parsed !== undefined) {
251	            finish({ success: true, output, parsed, latencyMs, level });
252	            return;
253	          }
254	          finish({
255	            success: false,
256	            output,
257	            error: 'Failed to parse JSON response',
258	            latencyMs,
259	            level,
260	          });
261	          return;
262	        }
263	        finish({ success: true, output, latencyMs, level });
264	        return;
265	      }
266	
267	      if (result.verdict === 'timeout') {
268	        finish({
269	          success: false,
270	          output: '',
271	          error: `OpenCode timeout after ${timeout}ms`,
272	          latencyMs,
273	          level,
274	        });
275	        return;
276	      }
277	
278	      // Any other verdict (e.g. 'error') — surface the bridge's reason.
279	      const reason = result.reason || 'opencode error';
280	      finish({
281	        success: false,
282	        output: '',
283	        error: reason,
284	        latencyMs,
285	        level,
286	      });
287	    });
288	  });
289	}
290	
291	/**
292	 * Run inference with configurable level
293	 */
294	export async function inference(options: InferenceOptions): Promise<InferenceResult> {
295	  const level = options.level || 'standard';
296	  const config = LEVEL_CONFIG[level];
297	  const startTime = Date.now();
298	  const timeout = options.timeout || config.defaultTimeout;
299	
300	  if (options.useOpencode) {
301	    const ocResult = await inferenceViaOpencode(options);
302	    if (ocResult.error !== 'opencode_unavailable') return ocResult;
303	    process.stderr.write('[Inference] OpenCode unavailable — falling back to Claude\n');
304	  }
305	
306	  return new Promise((resolve) => {
307	    // Unset CLAUDECODE so nested `claude` invocations don't trigger the
308	    // nested-session guard (hooks run inside Claude Code's environment).
309	    const env = { ...process.env };
310	    delete env.CLAUDECODE;
311	
312	    // BILLING: Always use subscription. Anthropic's credential precedence chain
313	    // (https://code.claude.com/docs/en/authentication#authentication-precedence)
314	    // puts BOTH ANTHROPIC_API_KEY and ANTHROPIC_AUTH_TOKEN above CLAUDE_CODE_OAUTH_TOKEN,
315	    // so either one in env will silently override OAuth. Bun auto-loads ~/.claude/.env
316	    // into child processes, and some MCP/plugin setups export ANTHROPIC_AUTH_TOKEN —
317	    // either path leaks subscription work onto API-key billing. Scrub both.
318	    delete env.ANTHROPIC_API_KEY;
319	    delete env.ANTHROPIC_AUTH_TOKEN;
320	
321	    const hasImages = options.imagePaths && options.imagePaths.length > 0;
322	    const args = [
323	      '--print',
324	      '--model', config.model,
325	      ...(hasImages ? ['--allowedTools', 'Read'] : ['--tools', '']),
326	      '--output-format', 'text',
327	      '--exclude-dynamic-system-prompt-sections',  // v3.23 C2: cache-friendly prompt prefix (claude-code v2.1.98+)
328	      '--setting-sources', '',
329	      '--system-prompt', options.systemPrompt,
330	    ];
331	
332	    const userPromptWithImages = hasImages
333	      ? `${options.imagePaths!.map((p) => `@${p}`).join('\n')}\n\n${options.userPrompt}`
334	      : options.userPrompt;
335	
336	    let stdout = '';
337	    let stderr = '';
338	
339	    const proc = spawn('claude', args, {
340	      env,
341	      stdio: ['pipe', 'pipe', 'pipe'],
342	    });
343	
344	    // Write prompt via stdin to avoid ARG_MAX limits on large inputs
345	    proc.stdin.write(userPromptWithImages);
346	    proc.stdin.end();
347	
348	    proc.stdout.on('data', (data) => {
349	      stdout += data.toString();
350	    });
351	
352	    proc.stderr.on('data', (data) => {
353	      stderr += data.toString();
354	    });
355	
356	    // Handle timeout
357	    const timeoutId = setTimeout(() => {
358	      proc.kill('SIGTERM');
359	      resolve({
360	        success: false,
361	        output: '',
362	        error: `Timeout after ${timeout}ms`,
363	        latencyMs: Date.now() - startTime,
364	        level,
365	      });
366	    }, timeout);
367	
368	    proc.on('close', (code) => {
369	      clearTimeout(timeoutId);
370	      const latencyMs = Date.now() - startTime;
371	
372	      if (code !== 0) {
373	        resolve({
374	          success: false,
375	          output: stdout,
376	          error: stderr || `Process exited with code ${code}`,
377	          latencyMs,
378	          level,
379	        });
380	        return;
381	      }
382	
383	      const output = stdout.trim();
384	
385	      // Parse JSON if requested
386	      if (options.expectJson) {
387	        // Try both object and array matches — use whichever parses successfully.
388	        // The greedy object regex /\{[\s\S]*\}/ can capture invalid substrings
389	        // when the LLM wraps a JSON array inside markdown or explanatory text
390	        // that happens to contain braces. By trying both candidates and
391	        // validating with JSON.parse, we handle arrays and objects reliably.
392	        const objectMatch = output.match(/\{[\s\S]*\}/);
393	        const arrayMatch = output.match(/\[[\s\S]*\]/);
394	
395	        for (const candidate of [objectMatch?.[0], arrayMatch?.[0]]) {
396	          if (!candidate) continue;
397	          try {
398	            const parsed = JSON.parse(candidate);
399	            resolve({
400	              success: true,
401	              output,
402	              parsed,
403	              latencyMs,
404	              level,
405	            });
406	            return;
407	          } catch { /* try next candidate */ }
408	        }
409	        resolve({
410	          success: false,
411	          output,
412	          error: 'Failed to parse JSON response',
413	          latencyMs,
414	          level,
415	        });
416	        return;
417	      }
418	
419	      resolve({
420	        success: true,
421	        output,
422	        latencyMs,
423	        level,
424	      });
425	    });
426	
427	    proc.on('error', (err) => {
428	      clearTimeout(timeoutId);
429	      resolve({
430	        success: false,
431	        output: '',
432	        error: err.message,
433	        latencyMs: Date.now() - startTime,
434	        level,
435	      });
436	    });
437	  });
438	}
439	
440	/**
441	 * Synthesize advisor state from the current ISA + recent activity (v3.24 P5).
442	 *
443	 * Closes the state-gaming Flaw identified by RedTeam review of v3.23 doctrine:
444	 * when the caller writes the state string manually, the same cognitive model
445	 * that might have missed the problem decides what the reviewer sees. Auto-synthesis
446	 * reads the ISA directly so the reviewer gets the unfiltered state.
447	 *
448	 * Reads:
449	 * - Current ISA content (resolved from MEMORY/STATE/work.json active session, or
450	 *   the most recently-updated ISA in MEMORY/WORK/)
451	 * - Recent session activity if available
452	 *
453	 * Returns a state string suitable for passing to advisor().
454	 */
455	export async function synthesizeAdvisorState(): Promise<string> {
456	  const fs = await import("fs/promises");
457	  const path = await import("path");
458	  const home = process.env.HOME || process.env.USERPROFILE || "";
459	  const workDir = path.join(home, ".claude", "PAI", "MEMORY", "WORK");
460	  const stateFile = path.join(home, ".claude", "PAI", "MEMORY", "STATE", "work.json");
461	
462	  // Try to read active session from work.json
463	  let activeSlug: string | undefined;
464	  try {
465	    const stateRaw = await fs.readFile(stateFile, "utf-8");
466	    const state = JSON.parse(stateRaw);
467	    activeSlug = state?.active || state?.current || state?.activeSession;
468	  } catch {
469	    // work.json may not exist — fall back to most recent ISA
470	  }
471	
472	  // Fall back: find most recently updated ISA in WORK/
473	  if (!activeSlug) {
474	    try {
475	      const entries = await fs.readdir(workDir, { withFileTypes: true });
476	      const dirs = entries.filter((e) => e.isDirectory()).map((e) => e.name);
477	      if (dirs.length === 0) {
478	        return "No active ISA found. Advisor state unavailable.";
479	      }
480	      // Sort by mtime
481	      const statted = await Promise.all(
482	        dirs.map(async (d) => {
483	          const s = await fs.stat(path.join(workDir, d));
484	          return { name: d, mtime: s.mtimeMs };
485	        }),
486	      );
487	      statted.sort((a, b) => b.mtime - a.mtime);
488	      activeSlug = statted[0].name;
489	    } catch (err) {
490	      return `Unable to locate active ISA: ${(err as Error).message}`;
491	    }
492	  }
493	
494	  // Read ISA content
495	  const isaPath = path.join(workDir, activeSlug, "ISA.md");
496	  let prdContent: string;
497	  try {
498	    prdContent = await fs.readFile(isaPath, "utf-8");
499	  } catch (err) {
500	    return `Active session ${activeSlug} has no ISA.md: ${(err as Error).message}`;
501	  }
502	
503	  // Truncate to a reasonable size for advisor context (first 300 lines, ~8KB)
504	  const MAX_LINES = 300;
505	  const lines = prdContent.split("\n");
506	  const truncated = lines.length > MAX_LINES
507	    ? lines.slice(0, MAX_LINES).join("\n") + `\n\n[... ISA truncated at ${MAX_LINES} lines of ${lines.length} total ...]`
508	    : prdContent;
509	
510	  return [
511	    `ISA: ${activeSlug}`,
512	    `Source: ${isaPath}`,
513	    ``,
514	    `--- ISA CONTENT (verbatim, auto-synthesized from disk — not caller-filtered) ---`,
515	    truncated,
516	    `--- END ISA CONTENT ---`,
517	  ].join("\n");
518	}
519	
520	/**
521	 * Advisor escalation — v3.24 Verification Doctrine.
522	 *
523	 * Calls smart tier (Opus) framed as a reviewer. Caller may supply explicit state
524	 * OR set autoSynthesize: true to have the helper read the current ISA automatically
525	 * (v3.24 P5 — closes state-gaming escape hatch).
526	 *
527	 * @param task          What the executor is trying to accomplish
528	 * @param state         Current relevant state (omit when autoSynthesize is true)
529	 * @param question      Specific question or decision point the executor faces
530	 * @param autoSynthesize If true, ignore `state` and read current ISA via synthesizeAdvisorState()
531	 * @param timeout       Override timeout in ms (default 120000)
532	 * @returns Structured advisory response
533	 *
534	 * Usage:
535	 *   import { advisor } from "./Inference";
536	 *
537	 *   // Manual state
538	 *   const review = await advisor({
539	 *     task: "Ship Algorithm v3.24.0",
540	 *     state: "Edited 8 files; ISC 28/30 passing; Inference.ts typecheck clean.",
541	 *     question: "Any gaps before declaring done?",
542	 *   });
543	 *
544	 *   // Auto-synthesized state (v3.24 P5 — recommended for commitment boundaries)
545	 *   const review = await advisor({
546	 *     task: "Ship Algorithm v3.24.0",
547	 *     question: "Any gaps before declaring done?",
548	 *     autoSynthesize: true,
549	 *   });
550	 *
551	 * Rules (from Algorithm v3.24.0 VERIFY doctrine):
552	 * - Call at commitment boundaries: before approach, when stuck, before declaring done
553	 * - Skip for MEASURED short reactive tasks (<4 min wall-clock AND <2 files)
554	 * - Extended+ ISA phase:complete = mandatory advisor call (P4)
555	 * - On conflict with empirical: re-call surfacing conflict, max 2 re-calls, then escalate (P1)
556	 */
557	export interface AdvisorOptions {
558	  task: string;
559	  state?: string;
560	  question: string;
561	  autoSynthesize?: boolean;
562	  timeout?: number;
563	  /** Opt-in: route the underlying inference call through the OpenCode bridge
564	   * (GPT-5.5). Falls back to Claude when the OpenCode server is unavailable. */
565	  useOpencode?: boolean;
566	}
567	
568	export async function advisor(options: AdvisorOptions): Promise<InferenceResult> {
569	  const systemPrompt = [
570	    "You are an advisor model invoked at a commitment boundary by an executor model.",
571	    "Review the executor's task, state, and specific question.",
572	    "Be direct. Flag risks the executor may have missed.",
573	    "If you see a fatal flaw, say so. If the approach is sound, confirm and say why.",
574	    "Your output will be weighed against empirical test results — a passing test does NOT invalidate your review.",
575	  ].join(" ");
576	
577	  // Resolve state: either auto-synthesized from ISA or caller-supplied.
578	  let resolvedState: string;
579	  if (options.autoSynthesize) {
580	    resolvedState = await synthesizeAdvisorState();
581	  } else if (options.state !== undefined) {
582	    resolvedState = options.state;
583	  } else {
584	    return {
585	      success: false,
586	      output: "",
587	      error: "advisor() requires either state or autoSynthesize: true",
588	      latencyMs: 0,
589	      level: 'smart',
590	    };
591	  }
592	
593	  const userPrompt = [
594	    `TASK: ${options.task}`,
595	    ``,
596	    `STATE:`,
597	    resolvedState,
598	    ``,
599	    `QUESTION: ${options.question}`,
600	    ``,
601	    `Advisory response:`,
602	  ].join("\n");
603	
604	  return inference({
605	    systemPrompt,
606	    userPrompt,
607	    level: 'smart',
608	    timeout: options.timeout ?? ADVISOR_TIMEOUT_MS,
609	    useOpencode: options.useOpencode,
610	  });
611	}
612	
613	/**
614	 * CLI entry point
615	 */
616	async function main() {
617	  const args = process.argv.slice(2);
618	
619	  // Parse flags
620	  let expectJson = false;
621	  let timeout: number | undefined;
622	  let level: InferenceLevel = 'standard';
623	  let mode: 'inference' | 'advisor' = 'inference';
624	  let autoState = false;  // v3.24 P5
625	  let useOpencode = false;
626	  const positionalArgs: string[] = [];
627	
628	  for (let i = 0; i < args.length; i++) {
